#!/usr/bin/env bash
set -euo pipefail

variant="${1:-}"
output="${2:-../../build_config.vh}"

case "$variant" in
8bit-mono)
    color_mode="MONO"
    output_width="8"
    ;;
8bit-k3)
    color_mode="K3"
    output_width="8"
    ;;
16bit-mono)
    color_mode="MONO"
    output_width="16"
    ;;
16bit-k3)
    color_mode="K3"
    output_width="16"
    ;;
*)
    echo "unknown Caster build variant: $variant" >&2
    echo "valid variants: 8bit-mono 8bit-k3 16bit-mono 16bit-k3" >&2
    exit 1
    ;;
esac

mkdir -p "$(dirname "$output")"
cat >"$output" <<EOF
// Generated by rtl/spartan6/par/write_build_config.sh.
\`ifndef CASTER_BUILD_CONFIG_VH
\`define CASTER_BUILD_CONFIG_VH

\`define CASTER_COLORMODE "$color_mode"
\`define CASTER_OUTPUT_WIDTH $output_width

\`endif
EOF
